function flattenSvg(root){
  root.querySelectorAll('radialGradient,linearGradient').forEach(function(g){
    var st = g.querySelectorAll('stop'); if (!st.length) return;
    var last = st[st.length - 1], col = last.getAttribute('stop-color') || last.style.stopColor;
    if (!col) return;
    st.forEach(function(x){ x.setAttribute('stop-color', col); x.style.stopColor = col; x.setAttribute('stop-opacity', 1); });
  });
}
function flattenVitals(root){
  var strip = root.querySelector('[data-tour=vitals]'); if (!strip) return;
  strip.querySelectorAll('div[style*="background"]').forEach(function(t){
    var st = t.getAttribute('style') || '', m = /background:\s*(#[0-9a-f]{3,8}|rgba?\([^)]*\))/i.exec(st);
    if (!m || /var\(/.test(m[1])) return;
    var col = m[1];
    if (/^rgba/i.test(col) && /,\s*0?\.\d+\)$/.test(col)) return;           // already a soft tint
    t.setAttribute('style', st.replace(/background:\s*(#[0-9a-f]{3,8}|rgba?\([^)]*\))/i, 'background:var(--c2);border:1px solid ' + col) + ';');
    t.querySelectorAll('*').forEach(function(x){ var xs = x.getAttribute('style') || ''; x.setAttribute('style', xs.replace(/color:\s*#fff[^;]*;?/i, 'color:' + col + ';')); });
  });
}

// ── Triage board ───────────────────────────────────────────────
function enhanceBoard(c){
  c.dataset.enh = 'board';
  // Quick-triage records carry a QUICK badge on the command board too (same as the casualty list).
  [].slice.call(c.querySelectorAll('.mci-card')).forEach(function(card){
    var m = /toggleMCICardExpand\('([^']+)'\)/.exec(card.getAttribute('onclick') || ''), rec = m && (W._incidentCasualties || []).filter(function(x){ return x._docId === m[1]; })[0];
    var row = card.querySelector('.mci-card-row');
    if (rec && rec.formLevel === 'quick' && row && !row.querySelector('.lvl')) row.insertAdjacentHTML('afterend', '<span class="lvl quick">' + ico('zap', 20) + L('QUICK TRIAGE','מיון מהיר') + '</span>');
  });
  kids(c).forEach(function(k){
    var s = styleOf(k), t = txt(k);
    if (/position:sticky/.test(s)) k.classList.add('b-modes');
    else if (/grid-template-columns:1fr 1fr 1fr 1fr/.test(s)) k.classList.add('b-kpis');
    else if (k.tagName === 'BUTTON' && /צמיד/.test(t)) k.classList.add('b-search');
    else if (/231,76,60,\.18|re-hi/.test(s) && k.children.length <= 2) k.classList.add('b-alert');
    else if (/230,126,34/.test(s) && /var\(--or\)/.test(s)) k.classList.add('b-next');
    else if (/justify-content:center/.test(s) && /\|/.test(t)) k.classList.add('b-stats');
  });
}

// MIST+ text -> labelled blocks. Each value is its own bidi island so Hebrew and numbers never scramble.
function hoBlocks(text){
  var E = W.escapeHtml, iso = function(s){ return '<bdi>' + E(s.replace(/[\u2066-\u2069]/g, '').trim()) + '</bdi>'; };
  var NAMES = { M:L('M · Mechanism','M · מנגנון'), I:L('I · Injuries','I · פציעות'), S:L('S · Signs','S · סימנים'), T:L('T · Treatment','T · טיפול') };
  var lines = String(text).split('\n').filter(function(x){ return x.trim(); }), out = '', blocks = [];
  var rank = function(k){ return k === 'M' ? 1 : k === 'I' ? 2 : k === 'S' ? 3 : /^(Consciousness|הכרה)/.test(k) ? 3.5 : k === 'T' ? 5 : /^(Tourniquet|TQ|ח״ע|חוסם|Drugs|Medications|תרופות|Blood|דם)/.test(k) ? 6 : 7; };
  lines.forEach(function(ln, n){
    var clean = ln.replace(/[\u2066-\u2069]/g, '');
    if (n === 0){ var hp = clean.split(' | '); var hoC = (W._incidentCasualties || []).filter(function(x){ return x._docId === W._casualtyEditId; })[0]; out += '<div class="ho-title">' + (W.casBadge ? W.casBadge({ name: W._casualtyName }, true) + ' ' : '') + iso(hp[0].replace(/^MIST\+\s*—\s*/, '')) + (W.casTag && hoC ? W.casTag(hoC) : '') + (hp[1] ? '<small>' + iso(hp[1]) + '</small>' : '') + '</div>'; return; }
    if (n === 1 && / \| /.test(clean)){ out += '<div class="ho-chips">' + clean.split(' | ').map(function(c){ return '<span>' + iso(c) + '</span>'; }).join('') + '</div>'; return; }
    var m = /^([^:]{1,40}):\s+(.*)$/.exec(clean);
    if (!m){ out += '<div class="ho-alert">' + iso(clean) + '</div>'; return; }
    var key = m[1].trim(), val = m[2], label = NAMES[key] || (/^(Consciousness|הכרה)/.test(key) ? L('S · Consciousness, GCS, pupils','S · הכרה, GCS, אישונים') : key), o0 = out; out = '';
    var items;
    if (key === 'S'){
      var tm = /^(.*?)\s*\(((?:trend|מגמה)[^:]*):\s*(.*)\)$/.exec(val);
      items = (tm ? tm[1] : val).split(' · ').map(function(x){ return '<span class="ho-v" dir="ltr">' + E(x) + '</span>'; }).join('');
      blocks.push({ r:rank(key), n:n, h:'<div class="ho-row ho-k-S"><b>' + E(label) + '</b><div class="ho-vs">' + items + '</div>' + (tm ? '<p>' + E(L('Trend: ','מגמה: ')) + iso(tm[3]) + '</p>' : '') + '</div>' }); out = o0;
      return;
    }
    var parts = val.split(/ · |, (?=[^\d])| \| /).filter(function(x){ return x.trim(); });
    blocks.push({ r:rank(key), n:n, h:'<div class="ho-row' + (NAMES[key] ? ' ho-k' : '') + '"><b>' + E(label) + '</b>' + (parts.length > 1 ? '<ul>' + parts.map(function(x){ return '<li>' + iso(x) + '</li>'; }).join('') + '</ul>' : '<p>' + iso(val) + '</p>') + '</div>' }); out = o0;
  });
  blocks.sort(function(a, b){ return a.r - b.r || a.n - b.n; });
  return '<div class="ho-body">' + out + blocks.map(function(b){ return b.h; }).join('') + '</div>';
}
